<?php
$e=static function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};
$u=function(array $p){return htmlspecialchars(html_entity_decode($this->uri($p),ENT_QUOTES|ENT_HTML5,'UTF-8'),ENT_QUOTES,'UTF-8');};
$contextCode=(string)$admissionCourse['contextcode'];
?>
<main class="chisimba-workspace membership-workspace">
<header class="membership-header"><div><p class="membership-eyebrow">Private course admission</p><h1><?php echo $e($admissionCourse['title']); ?></h1><p>Admit approved learners individually or from a reviewed list. Payment information is optional supporting evidence, not an admission requirement.</p></div><span class="membership-count"><?php echo count($admissionRows); ?> records</span></header>
<?php if($admissionMessage!==''):?><p class="chisimba-notice chisimba-notice--success chisimba-notice--transient" role="status"><?php echo $e(str_replace('_',' ',$admissionMessage));?>.</p><?php endif;?>
<?php if($admissionError!==''):?><p class="chisimba-notice chisimba-notice--error" role="alert">The change could not be completed: <?php echo $e(str_replace('_',' ',$admissionError));?>.</p><?php endif;?>
<section class="chisimba-form-card chisimba-form-card--wide"><div><h2>Add a learner for admission</h2><p>Select an approved learner and retain a short reason for the decision. You can admit them from the record immediately afterwards.</p></div>
<form method="post" action="<?php echo $u(array('action'=>'createadmission','contextcode'=>$contextCode));?>"><input type="hidden" name="csrf_token" value="<?php echo $e($admissionCsrf);?>"><input type="hidden" name="contextcode" value="<?php echo $e($contextCode);?>">
<label class="chisimba-form-field">Learner<select name="user_id" required><option value="">Choose a user…</option><?php foreach($admissionUsers as $p):?><option value="<?php echo $e($p['userid']);?>"><?php echo $e(trim($p['firstname'].' '.$p['surname']).' ('.$p['username'].')');?></option><?php endforeach;?></select></label>
<label class="chisimba-form-field">Admission status<select name="review_status"><option value="ready_for_admission">Ready for admission</option><option value="payment_under_review">Needs further review</option><option value="awaiting_payment">Waiting for external confirmation</option></select></label>
<label class="chisimba-form-field membership-reason">Reason or review note<input name="reason" maxlength="4000" required placeholder="For example: application approved"></label>
<details class="membership-supporting-details"><summary>Optional payment information</summary><p>Use this only when a payment record helps the reviewer confirm the decision.</p><label class="chisimba-form-field">Payment status<select name="payment_status"><option value="not_recorded">Not recorded</option><option value="pending">Pending</option><option value="paid">Paid</option><option value="failed">Failed</option><option value="refunded">Refunded</option><option value="disputed">Disputed</option></select></label><label class="chisimba-form-field">Payment reference<input name="payment_reference" maxlength="191"></label></details><div class="chisimba-form-actions"><button class="button" type="submit">Add admission record</button></div></form></section>
<section class="chisimba-form-card chisimba-form-card--wide"><div><h2>Admission records</h2><p>Current decisions and retained audit history.</p></div><?php if(empty($admissionRows)):?><p>No admission records yet.</p><?php else:?><div class="membership-table-wrap"><table class="membership-table"><thead><tr><th>Learner</th><th>Review</th><th>Payment</th><th>Reference</th><th>Actions</th></tr></thead><tbody><?php foreach($admissionRows as $r):?><tr><td><strong><?php echo $e($r['person']);?></strong><small><?php echo $e($r['username']);?></small></td><td><?php echo $e(str_replace('_',' ',$r['review_status']));?></td><td><?php echo $e(str_replace('_',' ',$r['payment_status']));?></td><td><?php echo $e($r['payment_reference']);?></td><td class="membership-actions"><?php if(!in_array($r['review_status'],array('admitted','revoked','declined'),true)):?><form method="post" action="<?php echo $u(array('action'=>'admit','contextcode'=>$contextCode));?>"><input type="hidden" name="csrf_token" value="<?php echo $e($admissionCsrf);?>"><input type="hidden" name="contextcode" value="<?php echo $e($contextCode);?>"><input type="hidden" name="admission_id" value="<?php echo $e($r['id']);?>"><button class="button" type="submit">Admit</button></form><details><summary>Edit review</summary><form method="post" action="<?php echo $u(array('action'=>'updateadmission','contextcode'=>$contextCode));?>"><input type="hidden" name="csrf_token" value="<?php echo $e($admissionCsrf);?>"><input type="hidden" name="contextcode" value="<?php echo $e($contextCode);?>"><input type="hidden" name="admission_id" value="<?php echo $e($r['id']);?>"><label>Status<select name="review_status"><option value="ready_for_admission" <?php echo $r['review_status']==='ready_for_admission'?'selected':'';?>>Ready for admission</option><option value="payment_under_review" <?php echo $r['review_status']==='payment_under_review'?'selected':'';?>>Needs further review</option><option value="awaiting_payment" <?php echo $r['review_status']==='awaiting_payment'?'selected':'';?>>Waiting for external confirmation</option><option value="declined">Declined</option></select></label><label>Reason or note<input name="reason" required maxlength="4000" value="<?php echo $e($r['reason']);?>"></label><label>Payment status<select name="payment_status"><?php foreach(array('not_recorded'=>'Not recorded','pending'=>'Pending','paid'=>'Paid','failed'=>'Failed','refunded'=>'Refunded','disputed'=>'Disputed') as $value=>$label):?><option value="<?php echo $e($value);?>" <?php echo $r['payment_status']===$value?'selected':'';?>><?php echo $e($label);?></option><?php endforeach;?></select></label><label>Payment reference<input name="payment_reference" maxlength="191" value="<?php echo $e($r['payment_reference']);?>"></label><button class="chisimba-button-secondary" type="submit">Save review</button></form></details><?php elseif($r['review_status']==='admitted'):?><form method="post" action="<?php echo $u(array('action'=>'revokeadmission','contextcode'=>$contextCode));?>"><input type="hidden" name="csrf_token" value="<?php echo $e($admissionCsrf);?>"><input type="hidden" name="contextcode" value="<?php echo $e($contextCode);?>"><input type="hidden" name="admission_id" value="<?php echo $e($r['id']);?>"><input name="reason" required maxlength="191" placeholder="Reason for revocation"><button class="chisimba-button-danger" type="submit">Revoke admission</button></form><?php else:?><span class="membership-audit-record">Audit record</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="chisimba-form-card chisimba-form-card--wide"><div><h2>Import reviewed candidates</h2><p>CSV columns must be: username, email, status, payment_reference, reason. The preview never creates users or admissions.</p></div><form enctype="multipart/form-data" method="post" action="<?php echo $u(array('action'=>'previewcsv','contextcode'=>$contextCode));?>"><input type="hidden" name="csrf_token" value="<?php echo $e($admissionCsrf);?>"><input type="hidden" name="contextcode" value="<?php echo $e($contextCode);?>"><label class="chisimba-form-field">CSV file<input type="file" name="admission_csv" accept=".csv,text/csv" required></label><button class="chisimba-button-secondary" type="submit">Preview import</button></form>
<?php if(!empty($admissionPreview)):?><h3>Preview</h3><table class="membership-table"><thead><tr><th>Line</th><th>Username</th><th>Email</th><th>Status</th><th>Result</th></tr></thead><tbody><?php foreach($admissionPreview as $r):?><tr><td><?php echo $e($r['line']);?></td><td><?php echo $e($r['username']);?></td><td><?php echo $e($r['email']);?></td><td><?php echo $e($r['status']);?></td><td><?php echo $r['valid']?'Ready':$e($r['error']);?></td></tr><?php endforeach;?></tbody></table><form method="post" action="<?php echo $u(array('action'=>'importcsv','contextcode'=>$contextCode));?>"><input type="hidden" name="csrf_token" value="<?php echo $e($admissionCsrf);?>"><input type="hidden" name="contextcode" value="<?php echo $e($contextCode);?>"><input type="hidden" name="preview_token" value="<?php echo $e($admissionPreview[0]['token']);?>"><button class="button" type="submit">Import valid records</button></form><?php endif;?></section>
</main>
